class DashTestSuite implements TestSuiteInterface {
  final StreamController<TestSuiteStatus> _statusController = StreamController<TestSuiteStatus>.broadcast();
  TestSuiteStatus _status = TestSuiteStatus.waiting;

  @override
  String get displayName => "Dash";

  @override
  Widget get icon => const Icon(Icons.flash_on, size: 32, color: Colors.blue);

  @override
  TestSuiteStatus get status => _status;

  @override
  Stream<TestSuiteStatus> get statusStream => _statusController.stream;

  void _updateStatus(TestSuiteStatus newStatus) {
    _status = newStatus;
    _statusController.add(newStatus);
  }

  @override
  Future<TestResult> runTests() async {
    try {
      _updateStatus(TestSuiteStatus.running);
      
      final stopwatch = Stopwatch()..start();
      final logs = <String>[];
      
      logs.add("Starting Dash test suite execution");
      
      // Get current test configuration (will be passed as parameter in the future)
      TestConfiguration? config; // TODO: Pass config as parameter to runTests()
      
      TestResult result;
      
      if (config?.mode == TestingMode.backupFile) {
        logs.add("Running backup file tests for Dash");
        result = await _runBackupFileTests(config!, logs);
      } else {
        logs.add("Running programmed vector tests for Dash");
        result = await _runProgrammedTests(logs);
      }
      
      stopwatch.stop();
      
      final finalResult = TestResult(
        success: result.success,
        message: result.message,
        logs: logs,
        executionTime: stopwatch.elapsed,
      );
      
      _updateStatus(finalResult.success ? TestSuiteStatus.passed : TestSuiteStatus.failed);
      return finalResult;
      
    } catch (e, stack) {
      _updateStatus(TestSuiteStatus.failed);
      Logging.instance.log("Dash test suite failed: $e", level: LogLevel.error, printFullLength: true);
      Logging.instance.log("Stack trace: $stack", level: LogLevel.error, printFullLength: true);
      
      return TestResult(
        success: false,
        message: "Dash test suite failed: $e",
        logs: ["Error: $e"],
        executionTime: Duration.zero,
      );
    }
  }

  Future<TestResult> _runProgrammedTests(List<String> logs) async {
    try {
      logs.add("Testing Dash wallet creation and address generation");
      
      // Test 1: Basic wallet creation and address generation
      if (!await _testBasicWalletCreation(logs)) {
        return TestResult(
          success: false,
          message: "Basic wallet creation test failed",
          logs: logs,
          executionTime: Duration.zero,
        );
      }
      
      // Test 2: InstantSend functionality testing
      logs.add("Testing Dash InstantSend functionality");
      if (!await _testInstantSendFeature(logs)) {
        logs.add("InstantSend test failed - continuing with other tests");
        // Note: InstantSend may fail in test environment, so we log but don't fail the suite
      }
      
      // Test 3: PrivateSend functionality testing
      logs.add("Testing Dash PrivateSend functionality");
      if (!await _testPrivateSendFeature(logs)) {
        logs.add("PrivateSend test failed - continuing with other tests");
        // Note: PrivateSend may fail in test environment, so we log but don't fail the suite
      }
      
      // Test 4: Masternode network connectivity
      logs.add("Testing Dash masternode network connectivity");
      if (!await _testMasternodeConnectivity(logs)) {
        logs.add("Masternode connectivity test failed - continuing with other tests");
      }
      
      // Test 5: X11 algorithm validation
      logs.add("Testing Dash X11 algorithm validation");
      if (!await _testX11AlgorithmValidation(logs)) {
        logs.add("X11 algorithm validation failed");
        return TestResult(
          success: false,
          message: "X11 algorithm validation failed",
          logs: logs,
          executionTime: Duration.zero,
        );
      }
      
      // Test 6: ChainLocks validation
      logs.add("Testing Dash ChainLocks validation");
      if (!await _testChainLocksValidation(logs)) {
        logs.add("ChainLocks validation failed - continuing with other tests");
      }
      
      logs.add("All Dash core tests completed successfully");
      return TestResult(
        success: true,
        message: "Dash test suite completed successfully",
        logs: logs,
        executionTime: Duration.zero,
      );
      
    } catch (e) {
      logs.add("Dash programmed tests failed: $e");
      return TestResult(
        success: false,
        message: "Dash programmed tests failed: $e",
        logs: logs,
        executionTime: Duration.zero,
      );
    }
  }

  Future<TestResult> _runBackupFileTests(TestConfiguration config, List<String> logs) async {
    try {
      logs.add("Starting Dash backup file restoration tests");
      
      // Step 1: Load and validate backup file
      final backupHandler = BackupFileHandler();
      final backupData = await backupHandler.loadBackupFile(
        config.backupFilePath!,
        config.backupPassphrase,
      );
      
      if (backupData == null) {
        return TestResult(
          success: false,
          message: "Failed to load Dash backup file",
          logs: logs,
          executionTime: Duration.zero,
        );
      }
      
      logs.add("Backup file loaded successfully");
      
      // Step 2: Filter for Dash wallets
      final dashWallets = backupData.wallets.where((w) => 
        w.coin.toLowerCase().contains('dash')).toList();
      
      if (dashWallets.isEmpty) {
        logs.add("No Dash wallets found in backup file");
        return TestResult(
          success: true,
          message: "No Dash wallets to test",
          logs: logs,
          executionTime: Duration.zero,
        );
      }
      
      logs.add("Found ${dashWallets.length} Dash wallet(s) in backup");
      
      // Step 3: Restore and test each wallet
      final restorationManager = WalletRestorationManager();
      final transactionExecutor = TransactionTestExecutor();
      
      int walletsRestored = 0;
      int transactionsAttempted = 0;
      int transactionsSuccessful = 0;
      final List<String> transactionIds = [];
      final Map<String, String> walletErrors = {};
      
      for (final walletData in dashWallets) {
        try {
          logs.add("Restoring Dash wallet: ${walletData.name}");
          
          final wallet = await restorationManager.restoreWallet(
            walletData,
            Dash(CryptoCurrencyNetwork.main),
          );
          
          if (wallet != null) {
            walletsRestored++;
            logs.add("Successfully restored wallet: ${walletData.name}");
            
            // Test a small self-spend transaction
            logs.add("Testing self-spend transaction for ${walletData.name}");
            transactionsAttempted++;
            
            final txResult = await transactionExecutor.executeSelfSpendTransaction(
              wallet,
              config.testAmount ?? "1000", // 1000 duffs (0.00001 DASH)
              config.feeRate ?? 1,
            );
            
            if (txResult.success && txResult.transactionId != null) {
              transactionsSuccessful++;
              transactionIds.add(txResult.transactionId!);
              logs.add("Self-spend transaction successful: ${txResult.transactionId}");
              
              // Test InstantSend on the transaction if supported
              if (await _testInstantSendTransaction(wallet, txResult.transactionId!, logs)) {
                logs.add("InstantSend validation successful for transaction");
              }
            } else {
              logs.add("Self-spend transaction failed: ${txResult.errorMessage}");
            }
          } else {
            walletErrors[walletData.name] = "Failed to restore wallet";
            logs.add("Failed to restore wallet: ${walletData.name}");
          }
        } catch (e) {
          walletErrors[walletData.name] = e.toString();
          logs.add("Error testing wallet ${walletData.name}: $e");
        }
      }
      
      final success = walletsRestored > 0 && walletErrors.isEmpty;
      final message = success 
        ? "Dash backup tests completed successfully"
        : "Some Dash backup tests failed";
      
      return BackupTestResult(
        success: success,
        message: message,
        logs: logs,
        executionTime: Duration.zero,
        walletsRestored: walletsRestored,
        transactionsAttempted: transactionsAttempted,
        transactionsSuccessful: transactionsSuccessful,
        transactionIds: transactionIds,
        walletErrors: walletErrors,
      );
      
    } catch (e) {
      logs.add("Dash backup file tests failed: $e");
      return TestResult(
        success: false,
        message: "Dash backup file tests failed: $e",
        logs: logs,
        executionTime: Duration.zero,
      );
    }
  }

